const updated = (raw.match(/^updated:\s*'?([\d-]+)/m) || [])[1] || '?';
const body = raw.replace(/^---[\s\S]*?\n---\n/, '');
const wanted = isGoals ? ['1', '2'] : ['3', '4', '5', '6'];
const sections = body.split(/^## /m).slice(1).filter(s => wanted.includes(s.split('.')[0]));

const clean = s => s.replace(/\*\*/g, '').replace(/\[\[[^\]|]*\|([^\]]+)\]\]/g, '$1').replace(/\[\[([^\]]+)\]\]/g, '$1');
const render = sec => {
  const lines = clean(sec).split('\n');
  const out = ['▪️ ' + lines.shift().replace(/^\d+\.\s*/, '').toUpperCase()];
  let header = null;
  for (const l of lines) {
    if (/^\|[-\s|]+\|$/.test(l)) continue;                 // table separator
    if (l.startsWith('|')) {
      const cells = l.split('|').slice(1, -1).map(c => c.trim());
      if (!header) { header = cells; continue; }
      out.push('• ' + cells[0] + ': ' + cells.slice(1).map((c, i) => header[i + 1] + ' ' + c).join(' / '));
      continue;
    }
    header = null;
    if (l.startsWith('### ')) out.push('', l.slice(4) + ':');
    else if (l.startsWith('- ')) out.push('• ' + l.slice(2));
    else out.push(l);
  }
  return out.join('\n').replace(/\n{3,}/g, '\n\n').trim();
};

if (!sections.length) {
  return [{ json: { text: '⚠️ Could not read the principles page (vault › triathlon-principles).' } }];
}
const title = isGoals ? '🎯 My goals' : '📜 My principles';
const parts = [title + ' (updated ' + updated + ')', ...sections.map(render), 'Edit in Obsidian: triathlon-principles'];

// Telegram caps a message at 4096 chars: pack sections into chunks, split long ones by paragraph
const chunks = [];
let cur = '';
for (const p of parts.flatMap(p => p.length > 3800 ? p.split('\n\n') : [p])) {
  if (cur && (cur + '\n\n' + p).length > 3800) { chunks.push(cur); cur = p; }
  else cur = cur ? cur + '\n\n' + p : p;
}
if (cur) chunks.push(cur);
return chunks.map(text => ({ json: { text } }));

