  { label: 'DPS', fn: swimDPS, fmt: v => v.toFixed(2) + ' m/cycle', betterUp: true },
]);

// Durability vs current target race demands — Triathlon du Lion L (86km bike / 19.5km run). Swap back to 90km/21km after the May 2027 race (see vault roadmap).
const maxKm = (list, c) => { const d = pick(list, c, 0).map(s => s.distance_m ? s.distance_m / 1000 : 0); return d.length ? Math.max(...d) : null; };
const dur = [];
const durLine = (label, r, p, race) => {
  if (r == null && p == null) return null;
  let out = '• ' + label + ' ' + (r != null ? r.toFixed(0) + 'km' : 'none');
  if (p != null) out += ' · was ' + p.toFixed(0);
  out += ' · race ' + race;
  return out;
};
const lr = durLine('Long ride', maxKm(recent, 'Ride'), maxKm(prior, 'Ride'), '86km');
const ln = durLine('Long run', maxKm(recent, 'Run'), maxKm(prior, 'Run'), '19.5km');
if (lr) dur.push(lr);
if (ln) dur.push(ln);
if (dur.length) sections.push(['🏁 Durability', ...dur].join('\n'));

// Recovery — ICU wellness (Get Progress Wellness, fullResponse: body = array of daily records)
try {
  const wBody = $('Get Progress Wellness').first().json.body;
  const wRecs = Array.isArray(wBody) ? wBody : [];
  const wRecent = wRecs.filter(w => (w.id || '') >= cut28);
  const wPrior = wRecs.filter(w => (w.id || '') < cut28);
  const avg = (list, f) => { const v = list.map(f).filter(x => x != null && isFinite(x) && x > 0); return v.length ? v.reduce((a, b) => a + b, 0) / v.length : null; };
  const wLine = (label, r, p, fmt, betterUp) => {
    if (r == null) return null;
    let out = '• ' + label + ' ' + fmt(r);
    if (p != null) {
      const pct = ((r - p) / p) * 100;
      const arrow = Math.abs(pct) < 1 ? '▬' : ((betterUp ? pct > 0 : pct < 0) ? '▲' : '▼');
      out += ' · was ' + fmt(p) + ' ' + arrow;
    }
    return out;
  };
  const fmtSleep = v => Math.floor(v / 3600) + 'h' + String(Math.round((v % 3600) / 60)).padStart(2, '0');
  const rec = [
    wLine('Sleep', avg(wRecent, w => w.sleepSecs), avg(wPrior, w => w.sleepSecs), fmtSleep, true),
    wLine('HRV', avg(wRecent, w => w.hrv), avg(wPrior, w => w.hrv), v => Math.round(v), true),
    wLine('RHR', avg(wRecent, w => w.restingHR), avg(wPrior, w => w.restingHR), v => Math.round(v) + ' bpm', false),
  ].filter(Boolean);
  if (rec.length) sections.push(['💤 Recovery', ...rec].join('\n'));
} catch (e) { /* wellness unavailable — skip section */ }

// CTL: latest vs last value before the 28d cut
const withCtl = all.filter(s => s.ctl != null).sort((a, b) => a.date < b.date ? -1 : 1);
if (withCtl.length) {
  const nowCtl = withCtl[withCtl.length - 1].ctl;
  const priCtlArr = withCtl.filter(s => s.date < cut28);
  const priCtl = priCtlArr.length ? priCtlArr[priCtlArr.length - 1].ctl : null;
  let l = '• CTL ' + Math.round(nowCtl);
  if (priCtl != null) l += ' · was ' + Math.round(priCtl) + ' ' + (Math.round(nowCtl) > Math.round(priCtl) ? '▲' : Math.round(nowCtl) < Math.round(priCtl) ? '▼' : '▬');
  sections.push('💪 Fitness\n' + l);
}

const scoreboard = sections.length
  ? '📈 Progress — last 4wk vs prior 4wk\n\n' + sections.join('\n\n')
  : '📈 Progress — not enough data yet.';
return [{ json: { scoreboard, hasData: sections.length > 0 } }];

const s = $('Get Explain Session').first().json;
const athlete = $input.first().json;
if (!s || s.error || !s.id) return [{ json: { notFound: true } }];

const isRun = (s.sport || '').toLowerCase().includes('run');
const fmt = (v, d = 1) => (v === null || v === undefined) ? null : Number(v).toFixed(d);
const met = [];
if (s.avg_hr) met.push('avg HR ' + s.avg_hr + 'bpm');
if (s.avg_power) met.push('avg power ' + s.avg_power + 'W');
if (s.normalized_power) met.push('NP ' + s.normalized_power + 'W');
if (s.avg_cadence) met.push('avg cadence ' + (isRun ? (s.avg_cadence * 2) + ' spm' : s.avg_cadence + ' rpm'));
if (s.avg_speed_ms) met.push('avg speed ' + fmt(s.avg_speed_ms, 2) + ' m/s');
if (s.tss) met.push('TSS ' + s.tss);
if (s.intensity_factor) met.push('IF ' + s.intensity_factor);
if (s.decoupling !== null && s.decoupling !== undefined) met.push('decoupling ' + fmt(s.decoupling) + '%');
if (s.efficiency_factor !== null && s.efficiency_factor !== undefined) met.push('EF ' + fmt(s.efficiency_factor, 2));
if (s.pool_length_m) met.push('pool ' + s.pool_length_m + 'm');

const lines = [
  'Sport: ' + s.sport + ' · Date: ' + s.date + ' · Grade: ' + (s.grade || '—'),
  'Duration: ' + (s.duration_min || '—') + 'min · Distance: ' + (s.distance_km ?? '—') + 'km',
];
if (met.length) lines.push('Metrics: ' + met.join(' · '));
lines.push('', 'COACH ANALYSIS (the message the athlete tapped):', s.analysis || '(no stored analysis — explain from the metrics alone)');
lines.push('', 'ATHLETE FITNESS PROFILE:', athlete['Fitness Profile'] || '');
return [{ json: { notFound: false, context: lines.join('\n') } }];

// /goals → sections 1-2 of the principles page, /principles → sections 3-6. Plain-text Telegram.
const cmd = ($('Telegram Trigger').first().json.message.text || '').trim().toLowerCase();
const isGoals = cmd.startsWith('/goals');
const raw = String($('Read Principles Page').first().json.stdout || '');
const updated = (raw.match(/^updated:\s*'?([\d-]+)/m) || [])[1] || '?';
const body = raw.replace(/^---[\s\S]*?\n---\n/, '');
const wanted = isGoals ? ['1', '2'] : ['3', '4', '5', '6'];
const sections = body.split(/^## /m).slice(1).filter(s => wanted.includes(s.split('.')[0]));

const clean = s => s.replace(/\*\*/g, '').replace(/\[\[[^\]|]*\|([^\]]+)\]\]/g, '$1').replace(/\[\[([^\]]+)\]\]/g, '$1');
const render = sec => {
  const lines = clean(sec).split('\n');
  const out = ['▪️ ' + lines.shift().replace(/^\d+\.\s*/, '').toUpperCase()];
  let header = null;
  for (const l of lines) {
    if (/^\|[-\s|]+\|$/.test(l)) continue;                 // table separator
    if (l.startsWith('|')) {
      const cells = l.split('|').slice(1, -1).map(c => c.trim());
      if (!header) { header = cells; continue; }
      out.push('• ' + cells[0] + ': ' + cells.slice(1).map((c, i) => header[i + 1] + ' ' + c).join(' / '));
      continue;
    }
    header = null;
    if (l.startsWith('### ')) out.push('', l.slice(4) + ':');
    else if (l.startsWith('- ')) out.push('• ' + l.slice(2));
    else out.push(l);
  }
  return out.join('\n').replace(/\n{3,}/g, '\n\n').trim();
};

if (!sections.length) {
  return [{ json: { text: '⚠️ Could not read the principles page (vault › triathlon-principles).' } }];
}
const title = isGoals ? '🎯 My goals' : '📜 My principles';
const parts = [title + ' (updated ' + updated + ')', ...sections.map(render), 'Edit in Obsidian: triathlon-principles'];

// Telegram caps a message at 4096 chars: pack sections into chunks, split long ones by paragraph
const chunks = [];
let cur = '';
for (const p of parts.flatMap(p => p.length > 3800 ? p.split('\n\n') : [p])) {
  if (cur && (cur + '\n\n' + p).length > 3800) { chunks.push(cur); cur = p; }
  else cur = cur ? cur + '\n\n' + p : p;
}
if (cur) chunks.push(cur);
return chunks.map(text => ({ json: { text } }));
